    if (n == 0) return;
    if ((unsigned int)(v.eos - v.finish) >= n) {
        E xc = x;
        unsigned int after = (unsigned int)(v.finish - pos);
        E* oldFinish = v.finish;
        if (after > n) {
            for (E* s = v.finish - n, *d = v.finish; s != v.finish; ++s, ++d) *d = *s;
            v.finish += n;
            for (E* s = oldFinish - n, *d = oldFinish; s != pos; ) *--d = *--s;
