struct Pair8 {                                       // test-only pair of the retail size 0x8: a key and its value words
    int Key;
    int Value[1];
};
static int gLoopCalls = 0;
static int gLastDepth = -1;
static int gFinalCalls = 0;
static int Lg(int n)
{
    int k;
    for (k = 0; n != 1; n >>= 1) ++k;
    return k;
