static void FinalInsertionSort(Pair8* first, Pair8* last)
{
    ++gFinalCalls;
    for (Pair8* i = first + 1; i < last; ++i) {
        Pair8 v = *i;
        Pair8* j = i;
        while (j != first && v.Key < (j - 1)->Key) { *j = *(j - 1); --j; }
        *j = v;
    }
}
static void Sort(Pair8* first, Pair8* last)
{
    if (first != last) {
        IntrosortLoop(first, last, Lg((int)(last - first)) * 2);
